/**
 * Scans a single line of a configuration document. Every directive fits on
 * one line, so a scanner never needs to look past the line it was built for.
 */
export class LineScanner {
  constructor(text, lineNo) {
    this.text = text
    this.len = text.length
    this.pos = 0
    this.lineNo = lineNo
  }

  fail(reason) {
    throw new ParseError(this.lineNo, reason)
  }

  peek() {
    return this.pos < this.len ? this.text[this.pos] : undefined
  }

  /** True once nothing meaningful remains: end of line or a comment. */
  atStructuralEnd() {
    const c = this.peek()
    return c === undefined || c === '#' || c === ';'
  }

  skipWs() {
    while (this.pos < this.len && (this.text[this.pos] === ' ' || this.text[this.pos] === '\t')) {
      this.pos++
    }
  }

  /** Requires nothing but trailing whitespace and an optional comment. */
  requireLineEnd(reason) {
    this.skipWs()
    if (!this.atStructuralEnd()) this.fail(reason)
  }

  isNameChar(c) {
    return c !== undefined && /[A-Za-z0-9_-]/.test(c)
  }

  parseName() {
    const c = this.peek()
    if (c === '"') return this.parseBasicString()
    if (c === "'") return this.parseLiteralString()
    const start = this.pos
    while (this.isNameChar(this.peek())) this.pos++
    if (this.pos === start) this.fail('expected a name')
    return this.text.slice(start, this.pos)
  }

  /** A dotted name: names joined by `.`, with spaces/tabs allowed around each dot. */
  parseNameList() {
    const names = []
    while (true) {
      this.skipWs()
      names.push(this.parseName())
      this.skipWs()
      if (this.peek() === '.') {
        this.pos++
        continue
      }
      break
    }
    return names
  }

  parseBasicString() {
    this.pos++ // opening quote
    let out = ''
    while (true) {
      if (this.pos >= this.len) this.fail('unterminated string')
      const c = this.text[this.pos]
      if (c === '"') {
        this.pos++
        return out
      }
      if (c === '\\') {
        this.pos++
        if (this.pos >= this.len) this.fail('unterminated string')
        const e = this.text[this.pos]
        if (e === '"') { out += '"'; this.pos++ }
        else if (e === '\\') { out += '\\'; this.pos++ }
        else if (e === 'n') { out += '\n'; this.pos++ }
        else if (e === 't') { out += '\t'; this.pos++ }
        else if (e === 'r') { out += '\r'; this.pos++ }
        else if (e === '0') { out += '\0'; this.pos++ }
        else if (e === 'u') {
          const hex = this.text.slice(this.pos + 1, this.pos + 5)
          if (hex.length < 4) this.fail('unterminated string')
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) this.fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(hex, 16))
          this.pos += 5
        } else {
          this.fail(`invalid escape \\${e}`)
        }
        continue
      }
      out += c
      this.pos++
    }
  }

  parseLiteralString() {
    this.pos++ // opening quote
    const start = this.pos
    while (true) {
      if (this.pos >= this.len) this.fail('unterminated string')
      if (this.text[this.pos] === "'") {
        const out = this.text.slice(start, this.pos)
        this.pos++
        return out
      }
      this.pos++
    }
  }

  /** A maximal run of characters that isn't whitespace, `,`, `]` or `}`. */
  readBareword() {
    const start = this.pos
    while (this.pos < this.len && !/[\s,\]}]/.test(this.text[this.pos])) this.pos++
    return this.text.slice(start, this.pos)
  }
}
