 * The value tree a configuration document is parsed into. Every node carries
 * a `kind` used both to render it and to enforce the assignment rules.
 */

export function makeTable() {
  return { kind: 'table', entries: new Map(), headerOpened: false }
}

export function makeArray(isArrayOfTables) {
  return { kind: 'array', isArrayOfTables, items: [] }
}

export function makeScalar(kind, value) {
  return { kind, value }
}
"}

