{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260921T220951Z/cell-Q1GORX/src/value-parser.js","content":"import { makeTable, makeArray, makeScalar } from './nodes.js'
import { assignInto } from './assign.js'

const INTEGER_RE = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function classifyBareword(word, scanner) {
  if (word === 'true') return makeScalar('boolean', true)
  if (word === 'false') return makeScalar('boolean', false)
  if (INTEGER_RE.test(word)) {
    return makeScalar('integer', Number(word.replace(/_/g, '')))
  }
  if ((word.includes('.') || /[eE]/.test(word)) && FLOAT_RE.test(word)) {
    return makeScalar('float', Number(word.replace(/_/g, '')))
  }
  scanner.fail(`invalid value ${word}`)
}

/**
 * Parses one value at the scanner's current position. `pathPrefix` is the
 * dotted path leading to this value, used to report duplicate-key and
 * not-a-table errors from inline tables nested inside it.
 */
export function parseValue(scanner, pathPrefix) {
  scanner.skipWs()
  if (scanner.atStructuralEnd() || scanner.peek() === ',' || scanner.peek() === ']' || scanner.peek() === '}') {
    scanner.fail('expected a value')
  }
  const c = scanner.peek()
  if (c === '"') return makeScalar('string', scanner.parseBasicString())
  if (c === "'") return makeScalar('string', scanner.parseLiteralString())
  if (c === '[') return parseArrayValue(scanner, pathPrefix)
  if (c === '{') return parseInlineTable(scanner, pathPrefix)
  const word = scanner.readBareword()
  return classifyBareword(word, scanner)
}

function parseArrayValue(scanner, pathPrefix) {
  scanner.pos++ // '['
  const array = makeArray(false)
  scanner.skipWs()
  if (scanner.peek() === ']') {
    scanner.pos++
    return array
  }
  while (true) {
    if (scanner.atStructuralEnd()) scanner.fail('unterminated array')
    const value = parseValue(scanner, pathPrefix)
    array.items.push(value)
    scanner.skipWs()
    if (scanner.atStructuralEnd()) scanner.fail('unterminated array')
    const c = scanner.peek()
    if (c === ',') {
      scanner.pos++
      scanner.skipWs()
      if (scanner.atStructuralEnd()) scanner.fail('unterminated array')
      if (scanner.peek() === ']') {
        scanner.pos++
        return array
      }
      continue
    }
    if (c === ']') {
      scanner.pos++
      return array
    }
    scanner.fail('trailing text after a value')
  }
}

function parseInlineTable(scanner, pathPrefix) {
  scanner.pos++ // '{'
  const table = makeTable()
  scanner.skipWs()
  if (scanner.peek() === '}') {
    scanner.pos++
    return table
  }
  while (true) {
    if (scanner.atStructuralEnd()) scanner.fail('unterminated inline table')
    const names = scanner.parseNameList()
    scanner.skipWs()
    if (scanner.atStructuralEnd()) scanner.fail('unterminated inline table')
    if (scanner.peek() !== '=') scanner.fail('expected = in an inline table')
    scanner.pos++
    scanner.skipWs()
    const value = parseValue(scanner, [...pathPrefix, ...names])
    assignInto(table, names, value, scanner.lineNo, pathPrefix)
    scanner.skipWs()
    if (scanner.atStructuralEnd()) scanner.fail('unterminated inline table')
    const c = scanner.peek()
    if (c === ',') {
      scanner.pos++
      scanner.skipWs()
      continue
    }
    if (c === '}') {
      scanner.pos++
