 * Renders a parsed document tree as JSON or as a `keys` listing.
 */

function compareByCodePoint(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const pa = ca[i].codePointAt(0)
    const pb = cb[i].codePointAt(0)
    if (pa !== pb) return pa - pb
  }
  return ca.length - cb.length
}

function sortedKeys(table) {
  return [...table.entries.keys()].sort(compareByCodePoint)
}

function indent(level) {
  return '  '.repeat(level)
}

function toJson(node, level) {
  if (node.kind === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const lines = keys.map((k) => `${indent(level + 1)}${JSON.stringify(k)}: ${toJson(node.entries.get(k), level + 1)}`)
    return `{\n${lines.join(',\n')}\n${indent(level)}}`
  }
  if (node.kind === 'array') {
    if (node.items.length === 0) return '[]'
    const lines = node.items.map((item) => `${indent(level + 1)}${toJson(item, level + 1)}`)
    return `[\n${lines.join(',\n')}\n${indent(level)}]`
  }
  if (node.kind === 'string') return JSON.stringify(node.value)
  if (node.kind === 'boolean') return node.value ? 'true' : 'false'
  // integer or float
  return JSON.stringify(node.value)
}

export function toJsonText(root) {
  return `${toJson(root, 0)}\n`
}

function walkKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.entries.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${typeOf(child)}`)
      walkKeys(child, childPath, out)
    }
  } else if (node.kind === 'array') {
    node.items.forEach((item, i) => {
      const childPath = `${path}[${i}]`
      out.push(`${childPath} ${typeOf(item)}`)
      walkKeys(item, childPath, out)
    })
  }
}

function typeOf(node) {
  return node.kind
}

export function toKeysText(root) {
  const out = []
  walkKeys(root, '', out)
  return out.length === 0 ? '' : `${out.join('\n')}\n`
}
"}

